/**
 * 3G MeLife Global Career & Occupational Taxonomy Master Dataset
 * 
 * 12 Domains, 36 Families, 72 Clusters, 108 Occupations
 * Calibrated multi-pillar profile vectors for assessment matching:
 * - Holland RIASEC (Realistic, Investigative, Artistic, Social, Enterprising, Conventional)
 * - Cognitive & Behavioral Skills
 * - Aptitude Task Affinities
 * - Learning Archetypes & Developmental Traits
 * - Academic Stream Alignments (Science PCM/PCB, Commerce, Humanities)
 * - Career Families (RCF, CCF, HCF)
 */

import {
  CareerDomainEntity,
  CareerFamilyEntity,
  CareerRelatedDimensions,
  FutureGrowthOutlook,
  LearningMilestone,
} from "../career.types";

export interface TaxonomyCareerSeed {
  career_code: string;
  slug: string;
  title: string;
  short_title: string;
  domain_code: string;
  family_code: string;
  cluster_code: string;
  specialization: string;
  category: string;
  industry: string;
  growth_category: string;
  future_growth: FutureGrowthOutlook;
  education_level: string;
  description: string;
  overview: string;
  core_skills: string[];
  supporting_skills: string[];
  knowledge_areas: string[];
  work_activities: string[];
  interest_areas: string[];
  work_styles: string[];
  academic_subjects: string[];
  recommended_subjects: string[];
  recommended_streams: string[];
  recommended_degrees: string[];
  typical_qualifications: string[];
  career_entry_path: string[];
  related_occupations: string[];
  work_environment: string[];
  technology_areas: string[];
  career_tags: string[];
  is_emerging: boolean;
  education_paths: string[];
  required_skills: string[];
  learning_roadmap: LearningMilestone[];
  sample_roles: string[];
  related_dimensions: CareerRelatedDimensions;
  display_order: number;
  translations?: Record<
    string,
    {
      title: string;
      specialization: string;
      category: string;
      industry: string;
      description: string;
      overview: string;
      required_skills?: string[];
      recommended_subjects?: string[];
    }
  >;
}

